#include <Adafruit_NeoPixel.h>
Adafruit_NeoPixel strip({{num_pixels}}, {{data_pin}}, NEO_GRB + NEO_KHZ800);

void setup() {
  strip.begin();
  strip.show();
}

void loop() {
  for (int i = 0; i < strip.numPixels(); i++) {
    strip.setPixelColor(i, strip.ColorHSV((i * 65536L) / strip.numPixels()));
  }
  strip.show();
  delay(50);
}
